parameters.jsCode:
// Parse Claude's response and extract JSON
const response = $input.first().json;
const content = response.content[0].text;

// Try to extract JSON from response
let biodata;
try {
  // Find JSON in the response
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    biodata = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in response');
  }
} catch (e) {
  return [{ json: { error: 'Failed to parse biodata', raw: content } }];
}

// Normalize field names
const normalized = {
  displayName: biodata.name || biodata.displayName || null,
  gender: biodata.gender || null,
  dateOfBirth: biodata.dateOfBirth || biodata.dob || null,
  division: biodata.division || null,
  district: biodata.district || null,
  upazila: biodata.upazila || biodata.area || null,
  education: biodata.education || null,
  occupation: biodata.occupation || null,
  monthlyIncome: biodata.monthlyIncome || biodata.income || null,
  maritalStatus: biodata.maritalStatus || null,
  fatherAlive: biodata.fatherAlive || null,
  motherAlive: biodata.motherAlive || null,
  siblings: biodata.siblings || null,
  prayerHabit: biodata.prayerHabit || null,
  beardOrHijab: biodata.beardOrHijab || biodata.beard || biodata.hijab || null,
  mazhab: biodata.mazhab || null,
  aboutMe: biodata.aboutMe || biodata.about || null,
  partnerPreferences: biodata.partnerPreferences || null,
  phoneNumber: biodata.phoneNumber || biodata.phone || null,
  guardianPhone: biodata.guardianPhone || null,
  source: 'telegram-bot'
};

return [{ json: normalized }];

